  "throughline": "The candidate consistently applies narrative and editorial skills to identify and engage individuals whose backgrounds do not align with standard job titles, bridging the gap between human story and technical requirement.",
  "throughline_evidence": [
    "What I am actually good at is finding people whose experience does not map cleanly to the job title.",
    "Before recruiting I spent over a decade in narrative, editorial, documentary and brand storytelling. That is not a detour. It is why I can tell you what is worth saying to a candidate, and why I do not let the machine say it."
  ],
  "unresolved_tension": "The candidate is currently building proprietary AI tools to automate sourcing while explicitly insisting on keeping human judgment in the loop, creating a tension between the efficiency of the machine and the narrative nuance of the human.",
  "tension_evidence": [
    "I use it to ship sourcing tools: market mapping that surfaces the talent pools a title search never returns, and candidate reads where every claim traces back to the person's own words.",
    "The machine finds people. A person decides what to say to them."
  ],
  "departures": [
    {
      "description": "Moved away from direct creative production and screenwriting roles to enter the corporate assistant and administrative sphere.",
      "evidence": "Assisted the writer/director with the writing, revising, proofreading  and submission of his screenplays to major studios.",
      "confidence": 0.9
    },
    {
      "description": "Left the high-pressure, zero-tolerance environment of elite entertainment executive assistance to pursue a more analytical role in film acquisitions.",
      "evidence": "High-stress environment performing execution-dependent tasks under extreme pressure, with the expectation of zero mistakes.",
      "confidence": 0.85
    },
    {
      "description": "Exited the film industry entirely to enter the healthcare technology sector as a sourcer.",
      "evidence": "Sourced Senior Software Engineer, mobile, AWS cloud, and related technology talent for a large healthcare organization.",
      "confidence": 0.95
    },
    {
      "description": "Moved away from a single-employer technical recruiting role to a consulting model serving multiple clients.",
      "evidence": "Representative client engagements included: Cambia Health Solutions, Groupon, Roblox, Grindr, YogaGlo, Tillster, Anthem Blue Cross, State Farm, Avanade, Rival Inc, LTK, Nielsen, USFoods, Newton Talent",
      "confidence": 0.9
    },
    {
      "description": "Left the consulting firm Hire4ce to found his own independent practice, Iconic.",
      "evidence": "This journey ultimately led to my role as a partner at Hire4ce, where I continued to shape sourcing strategies and contribute to the growth of the field.",
      "confidence": 0.95
    },
    {
      "description": "Shifted away from traditional manual sourcing methods to building and operating self-hosted LLM inference stacks.",
      "evidence": "Build and operate self-hosted LLM inference on local multi-GPU hardware using llama.cpp and open-weight models, with hands-on ownership of model deployment, orchestration, evaluation, prompt design, and the production realities of keeping it running.",
      "confidence": 0.9
    }
  ],
  "pursuits": [
    {
      "description": "Pursued a career in narrative and editorial storytelling, starting with assistant roles in film and publishing.",
      "evidence": "Assisted Mr. Anderson in his personal, professional and creative affairs during the distribution phase of THE ROYAL TENNENBAUMS and the writing and pre-production phase of THE LIFE AQUATIC.",
      "confidence": 0.9
    },
    {
      "description": "Pursued independent creative expression by writing and directing a documentary film.",
      "evidence": "MOUNTAINS OF HOPE, written and directed by Patrick Christell, produced by Kara-Lee Pool, explores the twin epidemics of AIDS/TB, exacerbated by the endemic doctor shortage in the landlocked African nation of Lesotho.",
      "confidence": 0.95
    },
    {
      "description": "Pursued expertise in talent sourcing by ghostwriting a seminal industry handbook and joining a sourcing institute.",
      "evidence": "Collaborated with sourcing industry pioneer Shally Steckerl to revise and restructure his seminal primer, The Talent Sourcing and Recruiting Handbook (later retitled The Sourcing Method), a comprehensive guide for both aspiring and experienced Talent Sourcing and Recruiting professionals.",
      "confidence": 0.95
    },
    {
      "description": "Pursued leadership and mentorship roles within the sourcing community, including board membership and mentoring disabled graduates.",
      "evidence": "leading me to take on leadership roles, speak at industry conferences, and mentor blind and disabled graduates of the Sourcing Institute Foundation.",
      "confidence": 0.9
    },
    {
      "description": "Pursued specialized recruiting in high-complexity, niche technical fields such as autonomous vehicles and aerospace.",
      "evidence": "Recruited highly specialized talent from game development, film and animation, semiconductor, aerospace, robotics, autonomous vehicle, and simulation organizations including Rockstar, Bethesda, Riot, Ubisoft, Sony, Disney, Pixar, Nvidia, Intel, Blue Origin, SpaceX, Waymo, and Zoox.",
      "confidence": 0.9
    },
    {
      "description": "Pursued the development of AI-driven tools that maintain human oversight over candidate judgment.",
      "evidence": "Design and apply agentic workflows to candidate discovery, talent research, and pipeline analysis, while keeping human review over candidate judgment and outreach.",
      "confidence": 0.95
    }
  ]
